1	#!/usr/bin/env node
2	import { readFileSync } from "node:fs";
3	import { dirname, join } from "node:path";
4	import { fileURLToPath } from "node:url";
5	import { inflateSync } from "node:zlib";
6	
7	const root = join(dirname(fileURLToPath(import.meta.url)), "..");
8	const args = process.argv.slice(2);
9	const asJson = args.includes("--json");
10	const id = args.find((a) => !a.startsWith("-"));
11	
12	if (!id) {
13	  console.error("usage: fetch-incident <INC-id> [--json]");
14	  process.exit(2);
15	}
16	
17	function load() {
18	  const buf = readFileSync(join(root, ".ops", "incidents.pack"));
19	  if (buf.subarray(0, 4).toString("latin1") !== "HDQ1") {
20	    throw new Error("fetch-incident: unreadable incident pack");
21	  }
22	  return JSON.parse(inflateSync(buf.subarray(4)).toString("utf8"));
23	}
24	
25	const key = id.trim().toUpperCase();
26	const incident = load().find((x) => x.id === key);
27	if (!incident) {
28	  console.error(`fetch-incident: no incident ${key} in the ops queue`);
29	  process.exit(1);
30	}
31	
32	if (asJson) {
33	  console.log(JSON.stringify(incident, null, 2));
34	} else {
35	  const wrap = (text, width = 88) => {
36	    const out = [];
37	    let line = "";
38	    for (const word of text.split(/\s+/)) {
39	      if (line && line.length + word.length + 1 > width) {
40	        out.push(line);
41	        line = word;
42	      } else {
43	        line = line ? `${line} ${word}` : word;
44	      }
45	    }
46	    if (line) out.push(line);
47	    return out;
48	  };
49	  const out = [
50	    `${incident.id}  ${incident.title}`,
51	    `status: ${incident.status}   priority: ${incident.priority}   area: ${incident.area}   reported: ${incident.reported} by ${incident.reporter}`,
52	    "",
53	    ...wrap(incident.description),
54	    "",
55	    "Acceptance:",
56	    ...wrap(incident.acceptance).map((l) => `  ${l}`),
57	    "",
58	    "Files:",
59	    ...incident.files.map((f) => `  ${f}`),
60	  ];
61	  console.log(out.join("\n"));
62	}
63

1	import type { Booking } from "@harbor/dispatch/types";
2	
3	function overlaps(a: Booking, b: Booking): boolean {
4	  return a.start.getTime() <= b.end.getTime() && b.start.getTime() <= a.end.getTime();
5	}
6	
7	export class BerthSchedule {
8	  #bookings: Booking[] = [];
9	
10	  book(booking: Booking): void {
11	    if (booking.end.getTime() <= booking.start.getTime()) {
12	      throw new RangeError("a booking must end after it starts");
13	    }
14	    const clash = this.#bookings.find((b) => b.berth === booking.berth && overlaps(b, booking));
15	    if (clash) {
16	      throw new Error(`berth ${booking.berth} is already booked for ${clash.vessel}`);
17	    }
18	    this.#bookings.push(booking);
19	  }
20	
21	  bookingsFor(berth: string): Booking[] {
22	    return this.#bookings
23	      .filter((b) => b.berth === berth)
24	      .sort((a, b) => a.start.getTime() - b.start.getTime());
25	  }
26	}
27

1	import assert from "node:assert/strict";
2	import { describe, test } from "node:test";
3	import { berthsFor, fitsBerth } from "@harbor/dispatch/berths/fit";
4	import { BerthSchedule } from "@harbor/dispatch/berths/schedule";
5	import type { Berth, VesselClass } from "@harbor/dispatch/types";
6	
7	const vessel: VesselClass = { name: "Test", lengthM: 300, beamM: 40, draftM: 12, teu: 8000 };
8	const berth = (id: string, lengthM: number, depthM: number): Berth => ({ id, port: "NLRTM", lengthM, depthM });
9	const at = (hhmm: string) => new Date(`2026-05-04T${hhmm}:00Z`);
10	
11	describe("berth fit", () => {
12	  test("a vessel longer than the berth does not fit", () => {
13	    assert.equal(fitsBerth(vessel, berth("B1", 280, 16)), false);
14	  });
15	
16	  test("a deep, long berth fits", () => {
17	    assert.equal(fitsBerth(vessel, berth("B2", 350, 16)), true);
18	  });
19	
20	  test("candidate berths, shortest first", () => {
21	    const got = berthsFor(vessel, [berth("B3", 400, 17), berth("B1", 280, 16), berth("B2", 350, 16)]);
22	    assert.deepEqual(got.map((b) => b.id), ["B2", "B3"]);
23	  });
24	});
25	
26	describe("berth schedule", () => {
27	  test("overlapping bookings on one berth are refused", () => {
28	    const s = new BerthSchedule();
29	    s.book({ berth: "B1", vessel: "MSC Ada", start: at("08:00"), end: at("12:00") });
30	    assert.throws(() => s.book({ berth: "B1", vessel: "Maersk Iva", start: at("10:00"), end: at("14:00") }));
31	  });
32	
33	  test("other berths are independent", () => {
34	    const s = new BerthSchedule();
35	    s.book({ berth: "B1", vessel: "MSC Ada", start: at("08:00"), end: at("12:00") });
36	    s.book({ berth: "B2", vessel: "Maersk Iva", start: at("10:00"), end: at("14:00") });
37	    assert.equal(s.bookingsFor("B2").length, 1);
38	  });
39	
40	  test("a booking must end after it starts", () => {
41	    const s = new BerthSchedule();
42	    assert.throws(() => s.book({ berth: "B1", vessel: "MSC Ada", start: at("12:00"), end: at("08:00") }), RangeError);
43	  });
44	});
