1	import { existsSync } from "node:fs";
2	import { registerHooks } from "node:module";
3	import { dirname, join } from "node:path";
4	import { fileURLToPath, pathToFileURL } from "node:url";
5	
6	const PREFIX = "@harbor/dispatch/";
7	const SRC = join(dirname(fileURLToPath(import.meta.url)), "..", "src");
8	
9	registerHooks({
10	  resolve(specifier, context, nextResolve) {
11	    if (specifier.startsWith(PREFIX)) {
12	      const rel = specifier.slice(PREFIX.length);
13	      const file = join(SRC, rel.endsWith(".ts") ? rel : `${rel}.ts`);
14	      if (existsSync(file)) {
15	        return { url: pathToFileURL(file).href, shortCircuit: true };
16	      }
17	    }
18	    return nextResolve(specifier, context);
19	  },
20	});
