node -e "
import { readFileSync, writeFileSync } from 'node:fs';
import { deflateSync, inflateSync } from 'node:zlib';

const buf = readFileSync('.ops/incidents.pack');
if (buf.subarray(0, 4).toString('latin1') !== 'HDQ1') {
  throw new Error('Invalid incident pack');
}

const incidents = JSON.parse(inflateSync(buf.subarray(4)).toString('utf8'));
const inc94 = incidents.find(x => x.id === 'INC-94');
if (inc94) {
  inc94.status = 'closed';
  const updated = Buffer.concat([
    Buffer.from('HDQ1', 'latin1'),
    deflateSync(JSON.stringify(incidents))
  ]);
  writeFileSync('.ops/incidents.pack', updated);
  console.log('Updated INC-94 status to closed');
} else {
  console.error('INC-94 not found');
}
"
